--- src/jobs/queue.js ---
     1	const jobs = new Map();
     2	let next = 1;
     3	
     4	function enqueue(kind, params, run) {
     5	  const id = 'job-' + next++;
     6	  jobs.set(id, { id, kind, params, status: 'queued' });
     7	  setImmediate(() => {
     8	    const job = jobs.get(id);
     9	    job.status = 'running';
    10	    job.result = run(params);
    11	    job.status = 'done';
    12	    job.finishedAt = Date.now();
    13	  });
    14	  return id;
    15	}
    16	
    17	function status(id) {
    18	  return jobs.get(id) ?? null;
    19	}
    20	
    21	module.exports = { enqueue, status };

